import { loadStripe } from "@stripe/stripe-js";
import React, { useEffect } from "react";
import toast from "react-hot-toast";
import { useDispatch, useSelector } from "react-redux";
import { addToCart } from "../../../slices/cartSlice";


// Initialize Stripe outside of component
const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY);

const CourseDetailsCard = ({ course, setConfirmationModal }) => {
    const { token } = useSelector((state) => state.auth);
    const { user } = useSelector((state) => state.profile);
    const { cart } = useSelector((state) => state.cart);
    const dispatch = useDispatch();

    useEffect(() => {
        console.log("Course Data:", course);
    }, [course]);

    const coursePrice = course?.price && !isNaN(parseFloat(course.price)) 
        ? `₹${parseFloat(course.price).toFixed(2)}` 
        : "N/A";
    const courseTitle = course?.title || "No Course Title";
    const courseInstructor = course?.instructor || "Unknown Instructor";

    const handleBuyCourse = async () => {
        console.log("Starting payment process...");

        if (!process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY) {
            console.error("❌ Stripe Publishable Key is missing in .env file");
            toast.error("Stripe configuration error. Contact support.");
            return;
        }

        if (token && user?.accountType === "Student") {
            try {
                const stripe = await stripePromise;

                if (!stripe) {
                    throw new Error('Stripe failed to initialize');
                }

                const response = await fetch(`${process.env.REACT_APP_BASE_URL}/create-checkout-session`, {
                    method: "POST",
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${token}`,
                    },
                    body: JSON.stringify({
                        products: [{
                            ...course,
                            courseId: course._id
                        }],
                        userId: user._id,
                    }),
                });

                if (!response.ok) {
                    throw new Error(`HTTP Error! Status: ${response.status}`);
                }

                const session = await response.json();
                console.log("Session created:", session);

                if (session.id) {
                    console.log("Redirecting to Stripe Checkout...");
                    const result = await stripe.redirectToCheckout({
                        sessionId: session.id,
                    });

                    if (result.error) {
                        throw new Error(result.error.message);
                    }
                } else {
                    throw new Error('Invalid session ID');
                }
            } catch (error) {
                console.error('❌ Error processing payment:', error);
                toast.error(error instanceof Error ? error.message : 'Payment failed');
            }
        } else {
            setConfirmationModal(true);
        }
    };

    if (!course) {
        return <p>Loading course details...</p>;
    }

    return (
        <div className="min-h-screen bg-gray-100 p-8">
            <div className="max-w-md mx-auto bg-white rounded-xl shadow-md overflow-hidden">
                <div className="p-8">
                    <div className="uppercase tracking-wide text-sm text-indigo-500 font-semibold">
                        Course Details
                    </div>
                    <h1 className="mt-2 text-xl font-bold text-gray-900">
                        {courseTitle}
                    </h1>
                    <p className="mt-2 text-gray-500">
                        {course.description}
                    </p>
                    <div className="mt-4">
                        <span className="text-2xl font-bold text-gray-900">
                            {coursePrice}
                        </span>
                    </div>
                    <button
                        onClick={handleBuyCourse}
                        className="mt-6 w-full bg-indigo-600 text-white py-2 px-4 rounded-lg hover:bg-indigo-700 transition-colors"
                    >
                        Buy Now
                    </button>

                    {user && user.accountType === "Student" && !cart.find((item) => item._id === course._id) && (
                        <button 
                            onClick={() => dispatch(addToCart(course))}
                            className="mt-4 w-full border border-indigo-600 text-indigo-600 py-2 px-4 rounded-lg hover:bg-indigo-50 transition-colors"
                        >
                            Add to Cart
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

export default CourseDetailsCard;
